 47	/* Cấu hình hệ thống xung nhịp lên 180 MHz từ HSE (Fact f-nguoi-81717370 do anh cho) */
 48	static void prvSetupClock180MHz(void)
 49	{
 50	    /* 1. Bật HSE */
 51	    RCC->CR |= RCC_CR_HSEON;
 52	    for (volatile uint32_t timeout = 0; timeout < 100000; timeout++) {
 53	        if (RCC->CR & RCC_CR_HSERDY) {
 54	            break;
 55	        }
 56	    }
 57	
 58	    /* 2. Bật clock PWR Controller và đặt chế độ Scale 1 */
 59	    RCC->APB1ENR |= RCC_APB1ENR_PWREN;
 60	    (void)RCC->APB1ENR;
 61	    PWR->CR |= PWR_CR_VOS;
 62	
 63	    /* 3. Đặt bộ chia bus APB1 = /4, APB2 = /2 */
 64	    RCC->CFGR |= RCC_CFGR_PPRE1_DIV4 | RCC_CFGR_PPRE2_DIV2;
 65	
 66	    /* 4. Cấu hình Main PLL: HSE / 8 * 360 / 2 = 180 MHz */
 67	    RCC->PLLCFGR = (8UL << RCC_PLLCFGR_PLLM_Pos)
 68	                 | (360UL << RCC_PLLCFGR_PLLN_Pos)
 69	                 | (0UL << RCC_PLLCFGR_PLLP_Pos)
 70	                 | RCC_PLLCFGR_PLLSRC_HSE
 71	                 | (7UL << RCC_PLLCFGR_PLLQ_Pos)
 72	                 | (6UL << RCC_PLLCFGR_PLLR_Pos);
 73	
 74	    /* 5. Bật PLL chính và chờ sẵn sàng */
 75	    RCC->CR |= RCC_CR_PLLON;
 76	    while (!(RCC->CR & RCC_CR_PLLRDY));
 77	
 78	    /* 6. Kích hoạt chế độ Over-Drive */
 79	    PWR->CR |= PWR_CR_ODEN;
 80	    while (!(PWR->CSR & PWR_CSR_ODRDY));
 81	    PWR->CR |= PWR_CR_ODSWEN;
 82	    while (!(PWR->CSR & PWR_CSR_ODSWRDY));
 83	
 84	    /* 7. Cấu hình Flash 5 Wait States, bật Prefetch, IC và DC */
 85	    FLASH->ACR = FLASH_ACR_LATENCY_5WS | FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;
 86	
 87	    /* 8. Chuyển nguồn SYSCLK sang PLL và chờ hoàn tất */
 88	    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
 89	    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);
 90	
 91	    /* 9. Cập nhật biến SystemCoreClock cho FreeRTOS và ngoại vi */
 92	    SystemCoreClock = 180000000UL;
 93	}
