 13	/* Cấu trúc gói tin truyền qua hàng đợi IPC */
 14	typedef struct {
 15	    uint32_t sender_id;
 16	    uint32_t sequence;
 17	    uint32_t timestamp;
 18	} app_msg_t;
 19	
 20	#define APP_QUEUE_CAPACITY 8U
 21	
 22	/* Vùng nhớ tĩnh cho hàng đợi và các tác vụ */
 23	static app_msg_t queue_storage[APP_QUEUE_CAPACITY];
 24	static rtos_queue_t app_queue;
 25	
 26	static rtos_tcb_t producer_tcb;
 27	static uint32_t producer_stack[RTOS_DEFAULT_STACK_WORDS];
 28	
 29	static rtos_tcb_t consumer_tcb;
 30	static uint32_t consumer_stack[RTOS_DEFAULT_STACK_WORDS];
 31	
 32	/* Biến thống kê trạng thái ứng dụng */
 33	static volatile uint32_t g_messages_sent = 0;
 34	static volatile uint32_t g_messages_received = 0;
 35	
 36	/**
 37	 * @brief Đồng bộ bộ đếm thời gian của HAL với nhịp của RTOS.
 38	 */
