 52	/**
 53	 * @brief Tác vụ sản xuất (Producer Task) - Mức ưu tiên 1.
 54	 *        Định kỳ đóng gói dữ liệu và gửi vào hàng đợi tĩnh IPC.
 55	 */
 56	static void producer_task(void *arg)
 57	{
 58	    (void)arg;
 59	    uint32_t seq = 0;
 60	
 61	    while (1) {
 62	        app_msg_t msg;
 63	        msg.sender_id = 1U;
 64	        msg.sequence = ++seq;
 65	        msg.timestamp = rtos_get_tick_count();
 66	
 67	        /* Gửi thông điệp vào hàng đợi với thời gian chờ 50 ms */
 68	        if (rtos_queue_send(&app_queue, &msg, 50U) == RTOS_OK) {
 69	            g_messages_sent++;
 70	        }
 71	
 72	        /* Tác vụ ngủ 100 ms nhường CPU cho tác vụ khác */
 73	        rtos_delay_ms(100U);
 74	    }
 75	}
 76	
 77	/**
 78	 * @brief Tác vụ tiêu thụ (Consumer Task) - Mức ưu tiên 2.
 79	 *        Lấy thông điệp từ hàng đợi và xử lý dữ liệu.
 80	 */
 81	static void consumer_task(void *arg)
 82	{
 83	    (void)arg;
 84	
 85	    while (1) {
 86	        app_msg_t rx_msg;
 87	
 88	        /* Chờ nhận dữ liệu từ hàng đợi với thời gian chờ 200 ms */
 89	        if (rtos_queue_receive(&app_queue, &rx_msg, 200U) == RTOS_OK) {
 90	            g_messages_received++;
 91	        }
 92	
 93	        /* Nhường quyền hoặc xử lý tiếp */
 94	        rtos_yield();
 95	    }
 96	}
