 32	/* Biến thống kê trạng thái ứng dụng */
 33	static volatile uint32_t g_messages_sent = 0;
 34	static volatile uint32_t g_messages_received = 0;
 35	
 36	/**
 37	 * @brief Đồng bộ bộ đếm thời gian của HAL với nhịp của RTOS.
