103	 *        Khởi tạo LCD DSI, SDRAM FMC, FT6206 và quét tương tác chạm.
104	 */
105	static void ui_task(void *arg)
106	{
107	    (void)arg;
108	    uint16_t x = 0;
109	    uint16_t y = 0;
110	
111	    UI_Init();
112	    Touch_Init();
113	
114	    while (1) {
