    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;

    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
