static void vTaskLED1(void *arg)
{
    (void)arg;
    for (;;) {
        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
        rtos_delay_ms(500U);
        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
        rtos_delay_ms(500U);
    }
}

